            aCross ^= (RotL64(aSoilLaneB[((S_BLOCK1 - aIndex + 10310U)) & S_BLOCK1], 13U) ^ RotL64(aSource[((aIndex + 11659U)) & S_BLOCK1], 35U));
            aCross = TwistMix64::DiffuseB(((aCross ^ aDomainWordCross) ^ aNonceWordG));
