            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0x956CFAF2BD8405E2ULL) + aOUSaltC[(((511U - aIndex) + 326U)) & S_SALT1];
            aOrbiterH = (((aOrbiterH ^ aOrbiterB) ^ 0x945D7F638AFB7C88ULL) ^ aOUSaltH[((aIndex + 281U)) & S_SALT1]) ^ aNonceWordL;
