    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSourceLane;
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0x8C143698FE75837FULL + 0xFD51C6D25E087F48ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0x8B67FC326FA48133ULL + 0x8D4EA4EBBE335581ULL);
