            aIngress ^= (RotL64(aLightningLaneD[((aIndex + 4662U)) & S_BLOCK1], 30U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 5915U)) & S_BLOCK1], 5U));
