            aCross = (RotL64(aIceLaneC[((S_BLOCK1 - aIndex + 4630U)) & S_BLOCK1], 35U) ^ RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 1373U)) & S_BLOCK1], 21U));
            aCross ^= (RotL64(aLightningLaneB[((S_BLOCK1 - aIndex + 1315U)) & S_BLOCK1], 5U) ^ RotL64(aSource[((S_BLOCK1 - aIndex + 487U)) & S_BLOCK1], 56U));
            aCross = TwistMix64::DiffuseC((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCross, 51U) + RotL64(aPrevious, 19U)) ^ (RotL64(aIngress, 3U) + RotL64(aCarry, 38U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterC = (aWandererF + RotL64(aIngress, 3U)) + 0xBB475F031C6BE96DULL;
            aOrbiterH = (aWandererJ + RotL64(aScatter, 5U)) + 0x14E974AFA86490F7ULL;
