            aOrbiterK = (aWandererA + RotL64(aScatter, 41U)) + 0xAA288EDA7A742F0FULL;
            aOrbiterI = ((aWandererH + RotL64(aPrevious, 51U)) + RotL64(aCarry, 57U)) + 0x3944A6D34748DF1CULL;
            //
