            aOrbiterF = ((aWandererC + RotL64(aIngress, 23U)) + 0x2A8AC5294D3B3C43ULL) + aOASaltD[((aIndex + 419U)) & S_SALT1];
            aOrbiterJ = ((aWandererK + RotL64(aScatter, 51U)) + RotL64(aCarry, 35U)) + 0xD10C5DC69D785BC3ULL;
            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x30BB3FB9CE0A44EBULL) + aOUSaltC[(((511U - aIndex) + 463U)) & S_SALT1];
